static void synscan_autohome_defers_tracking(void) {
	external_serial_simulator simulator = { 0 };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, mark, ":J1", 1));
	unsigned int revision = property_revision(MOUNT_TRACKING_PROPERTY_NAME);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME, true));
	indigo_usleep(300000);
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_TRACKING_PROPERTY_NAME)->state);
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_state_after(MOUNT_TRACKING_PROPERTY_NAME, INDIGO_OK_STATE, revision));
	assert_switch_item_value(MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME, true);
	SERIAL_CHECK_TRUE(last_synscan_command_line(&simulator, ":I1") > last_synscan_command_line(&simulator, ":E2"));
cleanup:
	if (context.connected) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_autohome_owns_previous_guide_pulse(void) {
	external_serial_simulator simulator = { 0 };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	SERIAL_CHECK_TRUE(synscan_start_tracking(&simulator) > 0);
	SERIAL_CHECK_TRUE(connect_sibling_guider());
	int pulse_mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property_1(&sibling_client, synscan_guider.device_name, GUIDER_GUIDE_RA_PROPERTY_NAME, GUIDER_GUIDE_WEST_ITEM_NAME, 500));
	for (int i = 0; i < 100 && atomic_load(&sibling_guide_state[1]) != INDIGO_BUSY_STATE; i++) {
		indigo_usleep(1000);
	}
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, atomic_load(&sibling_guide_state[1]));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, pulse_mark, ":I1", 1));
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":f1", "=011", 10000));
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, mark, ":K1", 1));
	for (int i = 0; i < 1000 && atomic_load(&sibling_guide_state[1]) == INDIGO_BUSY_STATE; i++) {
		indigo_usleep(1000);
	}
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, atomic_load(&sibling_guide_state[1]));
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, mark, ":I1", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, mark, ":J1", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_ALERT_STATE));
cleanup:
	remove_synscan_fault(&simulator);
	disconnect_sibling_guider();
	if (context.connected) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static double synscan_wire_pulse(external_serial_simulator *simulator, int mark, const char *start, const char *stop) {
	char path[PATH_MAX], line[256], command[128];
	double first = -1, last = -1, timestamp = 0;
	if (!simulator_fixture_path(path, sizeof(path), "%s.events", simulator->ready_file, NULL)) {
		return NAN;
	}
	FILE *file = fopen(path, "r");
	if (file == NULL) {
		return NAN;
	}
	int index = 0;
	while (fgets(line, sizeof(line), file)) {
		if (index++ < mark || sscanf(line, "%lf\t%127s", &timestamp, command) != 2) {
			continue;
		}
		if (first < 0 && !strncmp(command, start, strlen(start))) {
			first = timestamp;
		} else if (first >= 0 && !strncmp(command, stop, strlen(stop))) {
			last = timestamp;
			break;
		}
	}
	fclose(file);
	return first < 0 || last < 0 ? NAN : (last - first) * 1000;
}

static void synscan_guider_wire_timing(void) {
	external_serial_simulator simulator = { 0 };
	const char *items[] = { GUIDER_GUIDE_NORTH_ITEM_NAME, GUIDER_GUIDE_SOUTH_ITEM_NAME, GUIDER_GUIDE_EAST_ITEM_NAME, GUIDER_GUIDE_WEST_ITEM_NAME };
	const int durations[] = { 20, 100, 500 };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	SERIAL_CHECK_TRUE(synscan_start_tracking(&simulator) > 0);
	SERIAL_CHECK_TRUE(connect_sibling_guider());
	for (int workload = 0; workload < 2; workload++) {
		// The mount has no camera acquisition. Repeated property enumerations add bus
		// traffic to the ordinary tracking/poll workload; physical guide output is not measured.
		for (int direction = 0; direction < 4; direction++) {
			for (int duration = 0; duration < ARRAY_SIZE(durations); duration++) {
				for (int sample = -1; sample < 5; sample++) {
					int mark = synscan_mark(&simulator);
					if (workload) {
						indigo_enumerate_properties(&simulator_test_client, &INDIGO_ALL_PROPERTIES);
					}
					SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, sibling_pulse(direction < 2 ? GUIDER_GUIDE_DEC_PROPERTY_NAME : GUIDER_GUIDE_RA_PROPERTY_NAME, items[direction], durations[duration]));
					double measured = synscan_wire_pulse(&simulator, mark, direction < 2 ? ":J2" : ":I1", direction < 2 ? ":K2" : ":I1");
					SERIAL_CHECK_TRUE(isfinite(measured) && measured > 0);
					if (sample >= 0) {
						printf("GUIDE_WIRE %s %s %d %.6f\n", workload ? "enumeration" : "tracking", items[direction], durations[duration], measured);
					}
				}
			}
		}
	}
cleanup:
	disconnect_sibling_guider();
	if (context.connected) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void autohome_stop_failure(bool disconnect) {
	external_serial_simulator simulator = { 0 };
	bool started = false;
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	started = true;
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, mark, ":J1", 1));
	mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":L1", "!2", 1));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, disconnect ? CONNECTION_PROPERTY_NAME : MOUNT_ABORT_MOTION_PROPERTY_NAME, disconnect ? CONNECTION_DISCONNECTED_ITEM_NAME : MOUNT_ABORT_MOTION_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(disconnect ? CONNECTION_PROPERTY_NAME : MOUNT_ABORT_MOTION_PROPERTY_NAME, disconnect ? INDIGO_OK_STATE : INDIGO_ALERT_STATE));
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, mark, ":L2", NULL, 0, NULL) > 0);
	int stopped = last_synscan_command_line(&simulator, ":L2") + 1;
	indigo_usleep(300000);
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, stopped, ":J", NULL, 0, NULL));
	if (!disconnect) {
		SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_ALERT_STATE));
		// A refused emergency stop is reported, and a subsequent stop can be retried.
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true));
		SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_ABORT_MOTION_PROPERTY_NAME, INDIGO_OK_STATE));
	}
cleanup:
	remove_synscan_fault(&simulator);
	if (started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_autohome_abort_stop_failure(void) { autohome_stop_failure(false); }
static void synscan_autohome_disconnect_stop_failure(void) { autohome_stop_failure(true); }

static void synscan_autohome_abort_then_restart(void) {
	external_serial_simulator simulator = { 0 };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, mark, ":J1", 1));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_ALERT_STATE));
	unsigned int revision = property_revision(MOUNT_AUTOHOME_PROPERTY_NAME);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	for (int i = 0; i < 600 && find_cached_property(MOUNT_AUTOHOME_PROPERTY_NAME)->state == INDIGO_BUSY_STATE; i++) {
		indigo_usleep(100000);
	}
	SERIAL_CHECK_TRUE(wait_for_property_state_after(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_OK_STATE, revision));
	SERIAL_CHECK_TRUE(wait_for_light_item_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_HOME_ITEM_NAME, INDIGO_OK_STATE));
cleanup:
	if (context.connected) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_autohome_disconnect_with_guider(void) {
	external_serial_simulator simulator = { 0 };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	SERIAL_CHECK_TRUE(connect_sibling_guider());
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(autohome_wait_command(&simulator, mark, ":J1", 1));
	disconnect_serial_device(&synscan_mount);
	SERIAL_CHECK_TRUE(!context.connected);
	SERIAL_CHECK_TRUE(atomic_load(&sibling_guider_connected));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, sibling_pulse(GUIDER_GUIDE_DEC_PROPERTY_NAME, GUIDER_GUIDE_SOUTH_ITEM_NAME, 100));
cleanup:
	disconnect_sibling_guider();
	stop_serial_driver(&synscan_mount);
	stop_external_serial_simulator(&simulator);
}

// A sync within 5 degrees of the pole (the home position of a mount just switched on) is refused: the right ascension is
// ill-defined there and the alignment point would shift every later GoTo by hours, to the other side of the pier. The
// refusal adds no point, keeps the real coordinates on the bus and leaves the mount pointing GoTos where they belong.
static void synscan_mount_refuses_sync_near_the_pole(void) {
	static const char *items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	static const double latitudes[] = { 48, -35 };
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double latitude = NAN;
	char ra_mode[32], ra_increment[32], dec_mode[32], dec_increment[32];
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	latitude = cached_number_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME);
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	// the home position in both hemispheres: the hour angle +6 h of the northern and -6 h of the southern home, at the pole
	for (int i = ARRAY_SIZE(latitudes) - 1; i >= 0; i--) {
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property_1(&simulator_test_client, synscan_mount.device_name, GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME, latitudes[i]));
		SERIAL_CHECK_TRUE(wait_for_number_item_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME, latitudes[i], 0.001));
		double home_ra = synscan_fresh_raw(MOUNT_RAW_COORDINATES_RA_ITEM_NAME);
		double home_dec = cached_number_value(MOUNT_RAW_COORDINATES_PROPERTY_NAME, MOUNT_RAW_COORDINATES_DEC_ITEM_NAME);
		double sync_values[] = { fmod(synscan_lst() + (latitudes[i] > 0 ? -6 : 6) + 48, 24), latitudes[i] > 0 ? 90 : -90 };
		SERIAL_CHECK_TRUE(fabs(home_dec) > 85);
		SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
		atomic_store(&observed_coordinates_alert, false);
		pthread_mutex_lock(&observed_mutex);
		observed_coordinates_message[0] = 0;
		pthread_mutex_unlock(&observed_mutex);
		unsigned int alert = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE);
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, 2, items, sync_values));
		SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE, alert));
		SERIAL_CHECK_TRUE(atomic_load(&observed_coordinates_alert));
		SERIAL_CHECK_TRUE(observed_message_contains(observed_coordinates_message, "celestial pole"));
		double refused_ra = atomic_load(&observed_alert_ra);
		double refused_dec = atomic_load(&observed_alert_dec);
		double after_ra = synscan_fresh_raw(MOUNT_RAW_COORDINATES_RA_ITEM_NAME);
		double published_ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
		double published_dec = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
		printf("    latitude %+.0f: home raw %.4f h %+.4f deg, sync to %.4f h %+.4f deg refused; ALERT carried %.4f h %+.4f deg, the next poll %.4f h %+.4f deg, alignment points %d\n", latitudes[i], home_ra, home_dec, sync_values[0], sync_values[1], refused_ra, refused_dec, published_ra, published_dec, synscan_alignment_point_count());
		SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
		// the refusal and the following poll carry the real pointing, never the requested coordinates
		SERIAL_CHECK_TRUE(fabs(refused_dec - home_dec) < 0.01 && fabs(refused_dec - sync_values[1]) > 0.1);
		SERIAL_CHECK_TRUE(fabs(published_dec - home_dec) < 0.01 && fabs(published_dec - sync_values[1]) > 0.1);
		SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(published_ra - after_ra)) < 0.01);
		SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(refused_ra - home_ra)) < 0.01);
	}
	// northern hemisphere again: the GoTo after the refused sync goes where it went without it
	SERIAL_CHECK_TRUE(fabs(cached_number_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME) - 48) < 0.001);
	int mark = synscan_mark(&simulator);
	double date_ha = 2.5;
	double date_dec = 30;
	double ra = fmod(synscan_lst() - date_ha + 48, 24);
	double dec = date_dec;
	indigo_jnow_to_j2k(&ra, &dec);
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, ra, dec));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":G1", ra_mode, sizeof(ra_mode), NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":H1", ra_increment, sizeof(ra_increment), NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":G2", dec_mode, sizeof(dec_mode), NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":H2", dec_increment, sizeof(dec_increment), NULL));
	// a turn of the axis from its zero; the DEC axis past a quarter turn is the OTA west of the meridian, where the RA axis
	// turns the hour angle and the DEC axis a half turn less the declination, otherwise the other side of the pier
	double ra_position = 0.25 + (ra_mode[4] == '1' ? -1 : 1) * synscan_command_value(ra_increment) / SIM_STEPS_PER_REVOLUTION;
	double dec_position = 0.25 + (dec_mode[4] == '1' ? -1 : 1) * synscan_command_value(dec_increment) / SIM_STEPS_PER_REVOLUTION;
	bool west = dec_position >= 0.25 && dec_position < 0.75;
	double pointed_ha = synscan_wrap_hours(24 * (west ? ra_position : ra_position - 0.5));
	double pointed_dec = west ? 180 - 360 * dec_position : 360 * dec_position;
	printf("    GoTo to HA %.4f h DEC %+.4f deg of the date pointed the axes at HA %.4f h DEC %+.4f deg, OTA %s of the meridian\n", date_ha, date_dec, pointed_ha, pointed_dec, west ? "west" : "east");
	SERIAL_CHECK_TRUE(west);
	SERIAL_CHECK_TRUE(fabs(pointed_ha - date_ha) < 0.005);
	SERIAL_CHECK_TRUE(fabs(pointed_dec - date_dec) < 0.01);
	// a requested declination past the limit is refused away from the pole too, one below it adds its point
	double here_ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double far_values[] = { here_ra, 86 };
	double near_values[] = { here_ra, dec - 3 };
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
	atomic_store(&observed_coordinates_alert, false);
	pthread_mutex_lock(&observed_mutex);
	observed_coordinates_message[0] = 0;
	pthread_mutex_unlock(&observed_mutex);
	unsigned int alert = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, 2, items, far_values));
	SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE, alert));
	SERIAL_CHECK_TRUE(observed_message_contains(observed_coordinates_message, "celestial pole"));
	SERIAL_CHECK_TRUE(fabs(atomic_load(&observed_alert_dec) - dec) < 0.01);
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, 2, items, near_values));
	SERIAL_CHECK_TRUE(wait_for_synscan_alignment_point_count(1));

cleanup:
	remove_observer();
	if (driver_started) {
		if (synscan_alignment_point_count() > 0) {
			indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ALIGNMENT_DELETE_POINTS_PROPERTY_NAME, MOUNT_ALIGNMENT_DELETE_ALL_POINTS_ITEM_NAME, true);
			wait_for_synscan_alignment_point_count(0);
		}
		if (!isnan(latitude)) {
			indigo_change_number_property_1(&simulator_test_client, synscan_mount.device_name, GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME, latitude);
			wait_for_number_item_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME, latitude, 0.001);
		}
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// Starts a fresh coordinates log; every publication reaches the client, also one that repeats the previous state.
static void start_coordinates_log(void) {
	pthread_mutex_lock(&observed_mutex);
	coordinates_log_count = 0;
	pthread_mutex_unlock(&observed_mutex);
	simulator_test_client.force_property_updates = true;
	atomic_store(&coordinates_logging, true);
}

static int stop_coordinates_log(coordinates_event *events) {
	atomic_store(&coordinates_logging, false);
	pthread_mutex_lock(&observed_mutex);
	int count = coordinates_log_count;
	memcpy(events, coordinates_log, count * sizeof(*events));
	pthread_mutex_unlock(&observed_mutex);
	return count;
}

static void print_coordinates_log(const char *label, coordinates_event *events, int count) {
	static const char states[] = "IOBA";
	fprintf(stderr, "    %s:", label);
	for (int i = 0; i < count; i++) {
		fprintf(stderr, " %c%c", events[i].kind, states[events[i].state & 3]);
	}
	fprintf(stderr, "\n");
}

// Waits until `count` more polls published the raw coordinates.
static bool wait_for_synscan_polls(int count) {
	unsigned int revision = property_revision(MOUNT_RAW_COORDINATES_PROPERTY_NAME);
	for (int i = 0; i < 100 * count; i++) {
		if (property_revision(MOUNT_RAW_COORDINATES_PROPERTY_NAME) >= revision + count) {
			return true;
		}
		indigo_usleep(50000);
	}
	return false;
}

static unsigned int synscan_slew_busy_publications(void) {
	return atomic_load(&observed_slew_busy);
}

// The SLEW light of MOUNT_STATE is ALERT whenever the coordinates are, the ALERT that indigo_update_coordinates() keeps
// after a refused or failed request included. Checked once a whole poll ran after the call and again after each of
// `polls` more polls: a poll publishes the raw coordinates first, so when the next one has published them, the poll
// before it has published the coordinates and the lights.
static bool synscan_slew_light_alert_across_polls(const char *label, int polls) {
	if (!wait_for_synscan_polls(2)) {
		fprintf(stderr, "    %s: no polls\n", label);
		return false;
	}
	for (int i = 0; i <= polls; i++) {
		if (i > 0 && !wait_for_synscan_polls(1)) {
			fprintf(stderr, "    %s: no polls\n", label);
			return false;
		}
		indigo_property_state coordinates = find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state;
		indigo_property_state light = find_cached_item(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_SLEW_ITEM_NAME)->light.value;
		if (coordinates != INDIGO_ALERT_STATE || light != INDIGO_ALERT_STATE) {
			fprintf(stderr, "    %s: after poll %d the coordinates are %d and the SLEW light %d, both expected ALERT (%d)\n", label, i, coordinates, light, INDIGO_ALERT_STATE);
			return false;
		}
	}
	return true;
}

// The request that cleared a kept ALERT ended OK: the SLEW light was published BUSY since `busy` was taken from
// synscan_slew_busy_publications() and is IDLE with the coordinates OK now.
static bool synscan_slew_light_returned_to_idle(const char *label, unsigned int busy) {
	bool ok = synscan_slew_busy_publications() > busy && wait_for_light_item_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_SLEW_ITEM_NAME, INDIGO_IDLE_STATE) && find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state == INDIGO_OK_STATE;
	if (!ok) {
		fprintf(stderr, "    %s: %u SLEW light BUSY publications, the light is %d and the coordinates %d, expected BUSY, then IDLE and OK\n", label, synscan_slew_busy_publications() - busy, find_cached_item(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_SLEW_ITEM_NAME)->light.value, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	}
	return ok;
}

// The publications of one request: the first is its BUSY, the result follows BUSY publications only, then nothing but
// polls until the end of the log, all in the state of the result, at least `polls` of them; the result is published
// once, the next publication of the coordinates is a poll's. A poll that ran between the start of the log and the
// request, in the state before it, is skipped. MOUNT_HORIZONTAL_COORDINATES is published right before each publication
// of the equatorial coordinates, in the same state.
static bool check_coordinates_request(const char *label, coordinates_event *events, int count, indigo_property_state result, int polls) {
	int first = -1, outcome = -1, results = 0, poll_results = 0;
	bool ok = true;
	for (int i = 0; i < count && ok; i++) {
		if (events[i].kind != 'E') {
			continue;
		}
		bool poll = i >= 2 && events[i - 2].kind == 'R';
		if (i == 0 || events[i - 1].kind != 'H' || events[i - 1].state != events[i].state) {
			fprintf(stderr, "    %s: publication %d of the coordinates is not preceded by the horizontal coordinates in its state\n", label, i);
			ok = false;
		} else if (first < 0 && poll && events[i].state != INDIGO_BUSY_STATE) {
			continue;
		} else if (first < 0) {
			first = i;
			ok = events[i].state == INDIGO_BUSY_STATE;
		} else if (outcome < 0 && events[i].state != INDIGO_BUSY_STATE) {
			outcome = i;
			ok = events[i].state == result;
			results++;
		} else if (outcome >= 0) {
			ok = events[i].state == result;
			// a publication after the result must be a poll's, which publishes the raw coordinates first
			if (poll) {
				poll_results++;
			} else {
				results++;
			}
		}
	}
	ok = ok && first >= 0 && outcome >= 0 && results == 1 && poll_results >= polls;
	if (!ok) {
		fprintf(stderr, "    %s: expected BUSY, then one result %d and at least %d polls in it (results %d, polls %d)\n", label, result, polls, results, poll_results);
		print_coordinates_log(label, events, count);
	}
	return ok;
}

static bool synscan_request_coordinates(double ra, double dec) {
	static const char *items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	double values[] = { ra, dec };
	return indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, 2, items, values) == INDIGO_OK;
}

// A sync of the alignment model publishes BUSY, and its result once; a refusal stays ALERT across the following polls,
// also across a failed position readback, until the next request: an accepted sync ends OK, and so does a GoTo after a
// refused sync. An ALERT of a failed readback that follows OK is replaced by the next good poll, and a reconnection
// starts without the ALERT of the previous session. The SLEW light of MOUNT_STATE is ALERT while the refusal is kept and
// IDLE after the accepted sync.
static void synscan_mount_sync_publishes_busy_and_keeps_a_refusal(void) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	// a sync near the pole is refused anyway, so the mount leaves its home position first
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
	double ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double dec = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
	// a refused sync: BUSY, ALERT, and ALERT from the following polls
	pthread_mutex_lock(&observed_mutex);
	observed_coordinates_message[0] = 0;
	pthread_mutex_unlock(&observed_mutex);
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_request_coordinates(ra, 86));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	int count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("refused sync", events, count, INDIGO_ALERT_STATE, 3));
	SERIAL_CHECK_TRUE(observed_message_contains(observed_coordinates_message, "celestial pole"));
	SERIAL_CHECK_TRUE(synscan_slew_light_alert_across_polls("refused sync", 1));
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	SERIAL_CHECK_TRUE(fabs(cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) - dec) < 0.01);
	// a failed position readback publishes ALERT by itself, the next good poll keeps the ALERT of the refusal
	start_coordinates_log();
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":j1", "xyz", 1));
	for (int i = 0; i < 100 && synscan_fault_pending(&simulator); i++) {
		indigo_usleep(50000);
	}
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	int alerts = 0;
	for (int i = 0; i < count; i++) {
		if (events[i].kind == 'E') {
			SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, events[i].state);
			alerts++;
		}
	}
	SERIAL_CHECK_TRUE(alerts >= 2);
	// an accepted sync after the refused one: BUSY, OK, and OK from the following polls
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_request_coordinates(fmod(ra + 0.01, 24), dec + 0.05));
	SERIAL_CHECK_TRUE(wait_for_synscan_alignment_point_count(1));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(3));
	count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("accepted sync after a refused one", events, count, INDIGO_OK_STATE, 2));
	SERIAL_CHECK_EQ_INT(INDIGO_IDLE_STATE, find_cached_item(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_SLEW_ITEM_NAME)->light.value);
	SERIAL_CHECK_TRUE(fabs(cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) - (dec + 0.05)) < 0.01);
	// a GoTo after a refused sync: BUSY until it arrives, then OK
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_request_coordinates(ra, 86));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("second refused sync", events, count, INDIGO_ALERT_STATE, 1));
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 3 + 24, 24), 35));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("GoTo after a refused sync", events, count, INDIGO_OK_STATE, 2));
	// a failed readback that follows OK publishes ALERT, the next good poll OK again
	start_coordinates_log();
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":j1", "xyz", 1));
	for (int i = 0; i < 100 && synscan_fault_pending(&simulator); i++) {
		indigo_usleep(50000);
	}
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	int failed = -1, last = -1;
	for (int i = 0; i < count; i++) {
		if (events[i].kind == 'E') {
			if (failed < 0 && events[i].state == INDIGO_ALERT_STATE) {
				failed = i;
			}
			last = i;
		}
	}
	if (failed < 0 || last <= failed || events[last].state != INDIGO_OK_STATE) {
		print_coordinates_log("failed readback after OK", events, count);
	}
	SERIAL_CHECK_TRUE(failed >= 0 && last > failed && events[last].state == INDIGO_OK_STATE);
	// a refused sync, then a reconnection: the next session starts OK
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_request_coordinates(cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME), 86));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("refused sync before reconnection", events, count, INDIGO_ALERT_STATE, 1));
	disconnect_serial_device(&synscan_mount);
	SERIAL_CHECK_TRUE(!context.connected);
	SERIAL_CHECK_TRUE(connect_serial_device(&synscan_mount, NULL));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_HORIZONTAL_COORDINATES_PROPERTY_NAME)->state);
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_synscan_fault(&simulator);
	remove_observer();
	if (driver_started) {
		if (context.connected && synscan_alignment_point_count() > 0) {
			indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ALIGNMENT_DELETE_POINTS_PROPERTY_NAME, MOUNT_ALIGNMENT_DELETE_ALL_POINTS_ITEM_NAME, true);
			wait_for_synscan_alignment_point_count(0);
		}
		if (context.connected) {
			stop_serial_driver(&synscan_mount);
		} else {
			tear_down_serial_driver(&synscan_mount);
		}
	}
	stop_external_serial_simulator(&simulator);
}

// An abort that overtakes a queued sync cancels its handler: the sync must not keep the coordinates BUSY, no alignment point
// is added and the next GoTo is taken and ends OK. The device queue is held while the sync and the abort are requested, so
// the urgent abort runs before the handler of the sync.
static void synscan_mount_abort_cancels_a_queued_sync(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	bool queue_held = false;
	indigo_client finder = { .name = "SynScan queue finder", .version = INDIGO_VERSION_CURRENT, .define_property = abort_test_capture };
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
	double ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double dec = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
	abort_test_name = synscan_mount.device_name;
	abort_test_device = NULL;
	indigo_attach_client(&finder);
	indigo_enumerate_properties(&finder, &INDIGO_ALL_PROPERTIES);
	indigo_detach_client(&finder);
	SERIAL_CHECK_TRUE(abort_test_device != NULL);
	atomic_store(&abort_test_entered, false);
	atomic_store(&abort_test_released, false);
	atomic_store(&abort_test_drained, false);
	indigo_execute_handler(abort_test_device, abort_test_block);
	queue_held = true;
	SERIAL_CHECK_TRUE(abort_test_wait(&abort_test_entered));
	unsigned int busy = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_BUSY_STATE);
	SERIAL_CHECK_TRUE(synscan_request_coordinates(fmod(ra + 0.01, 24), dec + 0.05));
	SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_BUSY_STATE, busy));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true));
	indigo_execute_handler(abort_test_device, abort_test_drain);
	atomic_store(&abort_test_released, true);
	queue_held = false;
	SERIAL_CHECK_TRUE(abort_test_wait(&abort_test_drained));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	printf("    after the abort and 4 polls: coordinates state %d, alignment points %d\n", find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state, synscan_alignment_point_count());
	SERIAL_CHECK_TRUE(find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state != INDIGO_BUSY_STATE);
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 3 + 24, 24), 35));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
cleanup:
	if (queue_held) {
		atomic_store(&abort_test_released, true);
	}
	if (driver_started) {
		if (context.connected && synscan_alignment_point_count() > 0) {
			indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ALIGNMENT_DELETE_POINTS_PROPERTY_NAME, MOUNT_ALIGNMENT_DELETE_ALL_POINTS_ITEM_NAME, true);
			wait_for_synscan_alignment_point_count(0);
		}
		if (context.connected) {
			stop_serial_driver(&synscan_mount);
		} else {
			tear_down_serial_driver(&synscan_mount);
		}
	}
	stop_external_serial_simulator(&simulator);
}

// The ALERT that ends a GoTo, a park or a home in failure stays until the next request. Every end of a motion publishes
// the coordinates through indigo_update_coordinates(), which publishes the horizontal coordinates in the same state right
// before them and keeps an ALERT that follows BUSY: the polls after it report the unchanged pointing in ALERT, not OK.
// The refused slew of the GoTo handler, the failure seen by the GoTo, park and home finalizers and the abort of a GoTo, a
// park and an auto home used to publish their ALERT with indigo_update_property(), and the next poll replaced it with OK.
// A failed auto home published OK and then its ALERT, which did not follow BUSY and was not kept either.
typedef enum {
	SYNSCAN_MOTION_GOTO,
	SYNSCAN_MOTION_PARK,
	SYNSCAN_MOTION_HOME,
	SYNSCAN_MOTION_AUTOHOME
} synscan_motion;

static const char *synscan_motion_name(synscan_motion motion) {
	switch (motion) {
		case SYNSCAN_MOTION_GOTO:
			return "GoTo";
		case SYNSCAN_MOTION_PARK:
			return "park";
		case SYNSCAN_MOTION_HOME:
			return "home";
		default:
			return "auto home";
	}
}

// Starts the motion `degrees` away from the current pointing on both axes and returns when the coordinates are BUSY and
// the axes under way.
static bool synscan_start_motion(synscan_motion motion, double degrees) {
	double dec = synscan_fresh_raw(MOUNT_RAW_COORDINATES_DEC_ITEM_NAME);
	double ha = synscan_wrap_hours(synscan_lst() - cached_number_value(MOUNT_RAW_COORDINATES_PROPERTY_NAME, MOUNT_RAW_COORDINATES_RA_ITEM_NAME));
	double values[] = { synscan_wrap_hours(ha + degrees / 15), synscan_far_dec(dec, degrees) };
	unsigned int busy = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_BUSY_STATE);
	switch (motion) {
		case SYNSCAN_MOTION_GOTO:
			if (!synscan_start_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - values[0] + 48, 24), values[1])) {
				return false;
			}
			break;
		case SYNSCAN_MOTION_PARK: {
			static const char *items[] = { MOUNT_PARK_POSITION_HA_ITEM_NAME, MOUNT_PARK_POSITION_DEC_ITEM_NAME };
			if (indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_PARK_POSITION_PROPERTY_NAME, 2, items, values) != INDIGO_OK || !wait_for_property_state(MOUNT_PARK_POSITION_PROPERTY_NAME, INDIGO_OK_STATE)) {
				return false;
			}
			if (indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true) != INDIGO_OK || !wait_for_property_state(MOUNT_PARK_PROPERTY_NAME, INDIGO_BUSY_STATE)) {
				return false;
			}
			break;
		}
		case SYNSCAN_MOTION_HOME: {
			static const char *items[] = { MOUNT_HOME_POSITION_HA_ITEM_NAME, MOUNT_HOME_POSITION_DEC_ITEM_NAME };
			if (indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_HOME_POSITION_PROPERTY_NAME, 2, items, values) != INDIGO_OK || !wait_for_property_state(MOUNT_HOME_POSITION_PROPERTY_NAME, INDIGO_OK_STATE)) {
				return false;
			}
			if (indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, true) != INDIGO_OK || !wait_for_property_state(MOUNT_HOME_PROPERTY_NAME, INDIGO_BUSY_STATE)) {
				return false;
			}
			break;
		}
		case SYNSCAN_MOTION_AUTOHOME:
			if (indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true) != INDIGO_OK || !wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_BUSY_STATE)) {
				return false;
			}
			// the auto home moves the axes by small steps, two polls in BUSY are enough
			return wait_for_property_state_seen_after(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_BUSY_STATE, busy) && wait_for_synscan_polls(2) && find_cached_property(MOUNT_AUTOHOME_PROPERTY_NAME)->state == INDIGO_BUSY_STATE;
	}
	return wait_for_property_state_seen_after(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_BUSY_STATE, busy) && synscan_wait_for_dec_motion(dec, 3);
}

// A log started in the middle of a poll can open with the equatorial coordinates of that poll, whose horizontal
// coordinates came before the log; returns the index of the first event after them.
static int synscan_skip_partial_poll(const coordinates_event *events, int count) {
	int start = 0;
	while (start < count && events[start].kind == 'E') {
		start++;
	}
	return start;
}

// The motion is started, then its finalizer reads a refused axis status; both axes are stopped and the motion ends in
// ALERT, which the following polls keep, and the SLEW light of MOUNT_STATE with it; the next GoTo after a failed GoTo
// turns the light BUSY, then IDLE. The auto home queries the status of the axis it moves, either one.
static void motion_failure_keeps_alert(synscan_motion motion) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	const char *name = synscan_motion_name(motion);
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_start_motion(motion, 60));
	int mark = synscan_mark(&simulator);
	// the log opens with a poll of the running motion in BUSY
	start_coordinates_log();
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(1));
	// only the finalizers query the axis status, the poll reads the positions
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, motion == SYNSCAN_MOTION_AUTOHOME ? ":f" : ":f1", "!0", 1));
	// The auto home sends no ':f' while it polls a home index (about 4 s) and during the sensor clearance dwell (3 s)
	// that can follow, so it gets 30 s, safely longer than its longest stretch without one, whatever stage it is in
	int attempts = motion == SYNSCAN_MOTION_AUTOHOME ? 600 : 100;
	double armed = indigo_monotonic_time();
	for (int i = 0; i < attempts && synscan_fault_pending(&simulator); i++) {
		indigo_usleep(50000);
	}
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	double consumed = indigo_monotonic_time() - armed;
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	int count = stop_coordinates_log(events);
	int start = synscan_skip_partial_poll(events, count);
	printf("    failed %s: fault used after %.1f s, %d publications logged\n", name, consumed, count);
	SERIAL_CHECK_TRUE(check_coordinates_request(name, events + start, count - start, INDIGO_ALERT_STATE, 3));
	SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, mark, ":L1", NULL, 0, NULL) > 0);
	SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, mark, ":L2", NULL, 0, NULL) > 0);
	SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	SERIAL_CHECK_TRUE(synscan_slew_light_alert_across_polls(name, 2));
	if (motion == SYNSCAN_MOTION_GOTO) {
		unsigned int busy = synscan_slew_busy_publications();
		SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
		SERIAL_CHECK_TRUE(synscan_slew_light_returned_to_idle("GoTo after the failed GoTo", busy));
	}
	if (motion == SYNSCAN_MOTION_PARK) {
		SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, find_cached_property(MOUNT_PARK_PROPERTY_NAME)->state);
		SERIAL_CHECK_TRUE(find_cached_item(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME)->sw.value);
	} else if (motion == SYNSCAN_MOTION_HOME) {
		SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, find_cached_property(MOUNT_HOME_PROPERTY_NAME)->state);
	} else if (motion == SYNSCAN_MOTION_AUTOHOME) {
		SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, find_cached_property(MOUNT_AUTOHOME_PROPERTY_NAME)->state);
		assert_switch_item_value(MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, false);
	}
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_synscan_fault(&simulator);
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_mount_failed_goto_keeps_alert(void) {
	motion_failure_keeps_alert(SYNSCAN_MOTION_GOTO);
}

static void synscan_mount_failed_park_keeps_alert(void) {
	motion_failure_keeps_alert(SYNSCAN_MOTION_PARK);
}

static void synscan_mount_failed_home_keeps_alert(void) {
	motion_failure_keeps_alert(SYNSCAN_MOTION_HOME);
}

static void synscan_mount_failed_autohome_keeps_alert(void) {
	motion_failure_keeps_alert(SYNSCAN_MOTION_AUTOHOME);
}

// A successful auto home publishes BUSY and its OK once; the end of the auto home used to publish the coordinates twice.
static void synscan_mount_autohome_publishes_one_result(void) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	start_coordinates_log();
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	int count = stop_coordinates_log(events);
	int start = synscan_skip_partial_poll(events, count);
	printf("    auto home: %d publications logged\n", count);
	SERIAL_CHECK_TRUE(count < COORDINATES_LOG_SIZE);
	SERIAL_CHECK_TRUE(check_coordinates_request("auto home", events + start, count - start, INDIGO_OK_STATE, 3));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_HORIZONTAL_COORDINATES_PROPERTY_NAME)->state);
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The motion is started and aborted; the abort ends it in ALERT, which the following polls keep, and the SLEW light of
// MOUNT_STATE with it; the next GoTo after an aborted GoTo turns the light BUSY, then IDLE.
static void abort_keeps_alert(synscan_motion motion) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	const char *name = synscan_motion_name(motion);
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_start_motion(motion, 60));
	// the log opens with a poll of the running motion in BUSY
	start_coordinates_log();
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(1));
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	SERIAL_CHECK_TRUE(synscan_abort());
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	int count = stop_coordinates_log(events);
	int start = synscan_skip_partial_poll(events, count);
	printf("    aborted %s: %d publications logged\n", name, count);
	SERIAL_CHECK_TRUE(check_coordinates_request(name, events + start, count - start, INDIGO_ALERT_STATE, 3));
	SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state);
	SERIAL_CHECK_TRUE(synscan_slew_light_alert_across_polls(name, 2));
	if (motion == SYNSCAN_MOTION_GOTO) {
		unsigned int busy = synscan_slew_busy_publications();
		SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
		SERIAL_CHECK_TRUE(synscan_slew_light_returned_to_idle("GoTo after the aborted GoTo", busy));
	}
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_mount_aborted_goto_keeps_alert(void) {
	abort_keeps_alert(SYNSCAN_MOTION_GOTO);
}

static void synscan_mount_aborted_park_keeps_alert(void) {
	abort_keeps_alert(SYNSCAN_MOTION_PARK);
}

static void synscan_mount_aborted_autohome_keeps_alert(void) {
	abort_keeps_alert(SYNSCAN_MOTION_AUTOHOME);
}

// The publications of the equatorial coordinates from the first poll of the log on: a poll that read the position
// publishes the raw coordinates first, a poll whose readback failed does not. Returns the number of such failed polls
// and stores the index of each.
static int synscan_failed_polls(const coordinates_event *events, int count, int *failed, int size) {
	int first = -1, failures = 0;
	for (int i = 0; i < count; i++) {
		if (first < 0) {
			if (events[i].kind == 'R') {
				first = i;
			}
		} else if (events[i].kind == 'E' && i >= 2 && events[i - 2].kind != 'R' && failures < size) {
			failed[failures++] = i;
		}
	}
	return failures;
}

// Waits until the simulator logged since `mark` that the GoTo of each axis reached its target.
static bool synscan_wait_for_arrival(external_serial_simulator *simulator, int mark) {
	for (int i = 0; i < 600; i++) {
		if (count_synscan_commands(simulator, mark, "@arrived1", NULL, 0, NULL) > 0 && count_synscan_commands(simulator, mark, "@arrived2", NULL, 0, NULL) > 0) {
			return true;
		}
		indigo_usleep(50000);
	}
	return false;
}

// One failed position readback during a GoTo or a home is retried: the poll keeps the coordinates BUSY, and the motion,
// whose axes reach the target while the queue is held right after that poll, ends OK, followed by OK polls. The poll used
// to publish ALERT after BUSY, which indigo_update_coordinates() keeps, so the successful end of the motion was ALERT.
// The motion starts away from the pole: at the pole of the date the J2000 coordinates synscan_start_motion() takes the
// hour angle from are those of one fixed point whatever the RA axis position, so the hour angle it derived followed the
// sidereal time and the RA move of the motion took from almost nothing to several times the planned 20 degrees,
// depending on the time of day. At hour angle 2 h and declination 40 degrees both moves are 20 degrees, within the
// fraction of a degree between the J2000 and the date frame, at any sidereal time.
static void poll_failure_during_motion(synscan_motion motion) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	const char *name = synscan_motion_name(motion);
	int failed[8];
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
	int mark = synscan_mark(&simulator);
	// 20 degrees take about 2 s at the simulated high speed
	SERIAL_CHECK_TRUE(synscan_start_motion(motion, 20));
	start_coordinates_log();
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(1));
	// only the poll reads the positions while the axes run, the finalizer reads them once they stopped
	poll_failure_simulator = &simulator;
	atomic_store(&gate_entered, false);
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":j2", "!0", 1));
	atomic_store(&poll_failure_gate_armed, true);
	SERIAL_CHECK_TRUE(wait_for_gate());
	// the axes reach the target while the queue is held; the finalizer, due before the next poll, sees the stop first
	SERIAL_CHECK_TRUE(synscan_wait_for_arrival(&simulator, mark));
	atomic_store(&gate_release, true);
	for (int i = 0; i < 100 && find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state == INDIGO_BUSY_STATE; i++) {
		indigo_usleep(100000);
	}
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	int count = stop_coordinates_log(events);
	int failures = synscan_failed_polls(events, count, failed, ARRAY_SIZE(failed));
	int next = -1, later = 0;
	bool ok = failures == 1 && events[failed[0]].state == INDIGO_BUSY_STATE && events[failed[0] - 1].kind == 'H' && events[failed[0] - 1].state == INDIGO_BUSY_STATE;
	for (int i = failures > 0 ? failed[0] + 1 : count; ok && i < count; i++) {
		if (events[i].kind != 'E') {
			continue;
		}
		if (next < 0) {
			next = i;
		} else {
			later++;
		}
		ok = events[i].state == INDIGO_OK_STATE;
	}
	ok = ok && next >= 0 && later >= 2;
	if (!ok) {
		fprintf(stderr, "    %s: expected one failed poll in BUSY, then the end of the motion and the following polls in OK (failed polls %d)\n", name, failures);
		print_coordinates_log(name, events, count);
	}
	SERIAL_CHECK_TRUE(ok);
	if (motion == SYNSCAN_MOTION_HOME) {
		SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_HOME_PROPERTY_NAME)->state);
	}
cleanup:
	atomic_store(&poll_failure_gate_armed, false);
	atomic_store(&gate_release, true);
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_synscan_fault(&simulator);
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void synscan_mount_goto_survives_a_failed_poll(void) {
	poll_failure_during_motion(SYNSCAN_MOTION_GOTO);
}

static void synscan_mount_home_survives_a_failed_poll(void) {
	poll_failure_during_motion(SYNSCAN_MOTION_HOME);
}

// Position readbacks that keep failing during a GoTo: the first two failed polls keep the coordinates BUSY, the third
// publishes ALERT, which every later failed poll keeps.
static void synscan_mount_failed_polls_end_goto_alert(void) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	int failed[64];
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	// 60 degrees take more than 5 s, the failures start in the first second
	SERIAL_CHECK_TRUE(synscan_start_motion(SYNSCAN_MOTION_GOTO, 60));
	start_coordinates_log();
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(1));
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":j2", "!0", 1000));
	int failures = 0, count = 0;
	for (int i = 0; i < 100 && failures < 5; i++) {
		indigo_usleep(50000);
		pthread_mutex_lock(&observed_mutex);
		count = coordinates_log_count;
		memcpy(events, coordinates_log, count * sizeof(*events));
		pthread_mutex_unlock(&observed_mutex);
		failures = synscan_failed_polls(events, count, failed, ARRAY_SIZE(failed));
	}
	count = stop_coordinates_log(events);
	failures = synscan_failed_polls(events, count, failed, ARRAY_SIZE(failed));
	bool ok = failures >= 5;
	for (int i = 0; ok && i < failures; i++) {
		ok = events[failed[i]].state == (i < 2 ? INDIGO_BUSY_STATE : INDIGO_ALERT_STATE);
	}
	for (int i = failures >= 3 ? failed[2] : count; ok && i < count; i++) {
		ok = events[i].kind != 'E' || events[i].state == INDIGO_ALERT_STATE;
	}
	if (!ok) {
		fprintf(stderr, "    expected two failed polls in BUSY, then ALERT from the third on (failed polls %d)\n", failures);
		print_coordinates_log("failed polls", events, count);
	}
	SERIAL_CHECK_TRUE(ok);
	SERIAL_CHECK_TRUE(synscan_abort());
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_synscan_fault(&simulator);
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// A slew the controller refuses in the GoTo handler publishes BUSY, then the ALERT with the controller's reason once, and
// the following polls keep it; the next GoTo clears it, runs and ends OK.
static void synscan_mount_refused_goto_keeps_alert(void) {
	static coordinates_event events[COORDINATES_LOG_SIZE];
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	install_observer();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	double dec = synscan_fresh_raw(MOUNT_RAW_COORDINATES_DEC_ITEM_NAME);
	double target_ra = fmod(cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME) + 0.5, 24);
	double target_dec = synscan_far_dec(dec, 10);
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":G1", "!4", 1));
	pthread_mutex_lock(&observed_mutex);
	observed_coordinates_message[0] = 0;
	pthread_mutex_unlock(&observed_mutex);
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_request_coordinates(target_ra, target_dec));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(4));
	int count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	SERIAL_CHECK_TRUE(check_coordinates_request("refused GoTo", events, count, INDIGO_ALERT_STATE, 3));
	SERIAL_CHECK_TRUE(observed_message_contains(observed_coordinates_message, "not initialized"));
	SERIAL_CHECK_TRUE(fabs(synscan_fresh_raw(MOUNT_RAW_COORDINATES_DEC_ITEM_NAME) - dec) < 0.01);
	start_coordinates_log();
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, target_ra, target_dec));
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	count = stop_coordinates_log(events);
	SERIAL_CHECK_TRUE(check_coordinates_request("GoTo after a refused GoTo", events, count, INDIGO_OK_STATE, 2));
cleanup:
	atomic_store(&coordinates_logging, false);
	simulator_test_client.force_property_updates = false;
	remove_synscan_fault(&simulator);
	remove_observer();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// X_MOUNT_ENCODER_POSITION. The simulator started with --encoder-counts answers :d with the encoder ticks of the axis turn,
// SIM_ENCODER_COUNTS per revolution against the SIM_STEPS_PER_REVOLUTION steps of the step counter, as an AZ-GTi
// counts 1068 against 2073600, plus 512 ticks on RA and 1024 ticks on DEC, all around 0x800000. The driver has to
// publish that reply as it is, minus 0x800000, without knowing the resolution.
#define SIM_ENCODER_COUNTS               1068
#define SIM_ENCODER_COUNTS_TEXT          "1068"
#define SIM_RA_ENCODER_OFFSET            512
#define SIM_DEC_ENCODER_OFFSET           1024

// The offsets of the encoders of the running simulator, in counts: the defaults, or those of --encoder-offsets.
static long sim_encoder_offsets[2] = { SIM_RA_ENCODER_OFFSET, SIM_DEC_ENCODER_OFFSET };

static bool start_encoder_simulator(external_serial_simulator *simulator, const char *ra_features, const char *dec_features) {
	const char *arguments[] = { "--encoder-counts", SIM_ENCODER_COUNTS_TEXT, "--ra-features", ra_features, "--dec-features", dec_features, NULL };
	sim_encoder_offsets[0] = SIM_RA_ENCODER_OFFSET;
	sim_encoder_offsets[1] = SIM_DEC_ENCODER_OFFSET;
	return start_external_serial_simulator_with_args(simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE, arguments);
}

// The encoder ticks of a step counter alone, from the step zero 0x800000, rounded down, as the simulator counts them.
static long synscan_simulated_encoder_ticks(long step_counter) {
	return lrint(floor((double)(step_counter - 0x800000) * SIM_ENCODER_COUNTS / SIM_STEPS_PER_REVOLUTION));
}

// The step counter the simulator holds for an axis, replayed from its command log: the start value, the last :E that
// set it, each GoTo since, a :H increment or :S target started with :J in a GoTo mode (:G mode 0 or 2) with the
// direction of the mode, and the re-base of a :W..04 that enabled the dual encoder while the encoder disagreed: the
// counter becomes the encoder count times the steps per count, rounded towards zero, and the encoder offset 0. Valid
// while the axis only stands or completes its GoTos, as in the cases using it. `offset` receives the encoder offset.
static long synscan_replayed_axis(external_serial_simulator *simulator, char axis, long *offset) {
	char path[PATH_MAX];
	long position = axis == '1' ? 0x800000 : 0x800000 + lrint(SIM_STEPS_PER_REVOLUTION / 4);
	long encoder_offset = sim_encoder_offsets[axis == '1' ? 0 : 1];
	long increment = 0, target = 0;
	bool goto_mode = false, backward = false, increment_set = false, target_set = false;
	if (!simulator_fixture_path(path, sizeof(path), "%s.events", simulator->ready_file, NULL)) {
		return -1;
	}
	FILE *file = fopen(path, "r");
	if (file == NULL) {
		return -1;
	}
	char line[256];
	while (fgets(line, sizeof(line), file)) {
		char *command = strchr(line, '\t');
		if (command == NULL || command[1] != ':' || command[3] != axis) {
			continue;
		}
		command++;
		command[strcspn(command, "\r\n")] = 0;
		char mode_digits[2][2] = { { command[3], 0 }, { command[4], 0 } };
		switch (command[1]) {
			case 'E':
				position = synscan_command_value(command);
				break;
			case 'G':
				goto_mode = (strtol(mode_digits[0], NULL, 16) & 1) == 0;
				backward = (strtol(mode_digits[1], NULL, 16) & 1) != 0;
				break;
			case 'H':
				increment = synscan_command_value(command);
				increment_set = true;
				target_set = false;
				break;
			case 'S':
				target = synscan_command_value(command);
				target_set = true;
				increment_set = false;
				break;
			case 'J':
				if (goto_mode && increment_set) {
					position += backward ? -increment : increment;
				} else if (goto_mode && target_set) {
					position = target;
				}
				increment_set = target_set = false;
				break;
			case 'W':
				if (synscan_command_value(command) == 4 && encoder_offset != 0) {
					long long product = (long long)(synscan_simulated_encoder_ticks(position) + encoder_offset) * lrint(SIM_STEPS_PER_REVOLUTION);
					position = 0x800000 + (long)(product >= 0 ? (product + SIM_ENCODER_COUNTS - 1) / SIM_ENCODER_COUNTS : -(-product / SIM_ENCODER_COUNTS));
					encoder_offset = 0;
				}
				break;
		}
	}
	fclose(file);
	if (offset != NULL) {
		*offset = encoder_offset;
	}
	return position;
}

static long synscan_replayed_step_counter(external_serial_simulator *simulator, char axis) {
	return synscan_replayed_axis(simulator, axis, NULL);
}

// The counts of both axes the simulator answers :d with now, minus 0x800000.
static void synscan_simulated_encoder_counts(external_serial_simulator *simulator, long *ra, long *dec) {
	long ra_offset = 0, dec_offset = 0;
	*ra = synscan_simulated_encoder_ticks(synscan_replayed_axis(simulator, '1', &ra_offset)) + ra_offset;
	*dec = synscan_simulated_encoder_ticks(synscan_replayed_axis(simulator, '2', &dec_offset)) + dec_offset;
}

// The X_MOUNT_ENCODER_POSITION values after the third poll from this call; false unless they are OK. The bus publishes the
// property only when its values or state change, which they do not while the axes stand, so the polls are counted on
// MOUNT_RAW_COORDINATES, whose right ascension follows the sidereal time. A poll publishes the encoder position after
// the raw coordinates, so the values are at least those of the second poll, which read the axes after the call.
static bool synscan_fresh_encoder(double *ra, double *dec) {
	unsigned int revision = property_revision(MOUNT_RAW_COORDINATES_PROPERTY_NAME);
	for (int i = 0; i < 150; i++) {
		indigo_usleep(50000);
		if (property_revision(MOUNT_RAW_COORDINATES_PROPERTY_NAME) > revision + 2) {
			*ra = cached_number_value(MOUNT_ENCODER_POSITION_PROPERTY_NAME, MOUNT_ENCODER_POSITION_RA_ITEM_NAME);
			*dec = cached_number_value(MOUNT_ENCODER_POSITION_PROPERTY_NAME, MOUNT_ENCODER_POSITION_DEC_ITEM_NAME);
			indigo_property *property = find_cached_property(MOUNT_ENCODER_POSITION_PROPERTY_NAME);
			return property != NULL && property->state == INDIGO_OK_STATE;
		}
	}
	fprintf(stderr, "    no fresh poll for %s\n", MOUNT_ENCODER_POSITION_PROPERTY_NAME);
	return false;
}

// Fresh published values equal to what the simulator answers :d with; prints both.
static bool synscan_encoder_matches_simulator(external_serial_simulator *simulator, const char *where, double *ra, double *dec) {
	long expected_ra = 0, expected_dec = 0;
	bool fresh = synscan_fresh_encoder(ra, dec);
	synscan_simulated_encoder_counts(simulator, &expected_ra, &expected_dec);
	printf("    %s: RA %.0f DEC %.0f published, the simulator answers RA %ld DEC %ld (step counters %ld %ld)\n", where, *ra, *dec, expected_ra, expected_dec, synscan_replayed_step_counter(simulator, '1') - 0x800000, synscan_replayed_step_counter(simulator, '2') - 0x800000);
	return fresh && *ra == expected_ra && *dec == expected_dec;
}

// Selects which encoders X_MOUNT_USE_ENCODERS uses for the coordinates and waits until the mount accepted it.
static bool synscan_select_encoders(bool ra, bool dec) {
	static const char *items[] = { MOUNT_USE_RA_ENCODER_ITEM_NAME, MOUNT_USE_DEC_ENCODER_ITEM_NAME };
	bool values[] = { ra, dec };
	unsigned int revision = property_revision(MOUNT_USE_ENCODERS_PROPERTY_NAME);
	if (indigo_change_switch_property(&simulator_test_client, synscan_mount.device_name, MOUNT_USE_ENCODERS_PROPERTY_NAME, 2, items, values) != INDIGO_OK) {
		return false;
	}
	return wait_for_property_state_after(MOUNT_USE_ENCODERS_PROPERTY_NAME, INDIGO_OK_STATE, revision) && find_cached_item(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_RA_ENCODER_ITEM_NAME)->sw.value == ra && find_cached_item(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_DEC_ENCODER_ITEM_NAME)->sw.value == dec;
}

// X_MOUNT_ENCODER_POSITION is a read-only integer number in the alignment group with the 24-bit signed range. A mount with
// an encoder on one axis only defines it too: that axis shows its encoder count, the axis without an encoder shows 0
// and is never asked for an encoder reading. A client request to change it changes nothing.
static void synscan_mount_encoder_position_with_one_encoder(void) {
	static const char *items[] = { MOUNT_ENCODER_POSITION_RA_ITEM_NAME, MOUNT_ENCODER_POSITION_DEC_ITEM_NAME };
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	for (int axis = 0; axis < 2; axis++) {
		bool ra_encoder = axis == 0;
		SERIAL_CHECK_TRUE(start_encoder_simulator(&simulator, ra_encoder ? "6001" : "6000", ra_encoder ? "6000" : "6001"));
		SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
		driver_started = true;
		SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
		assert_property_has_items(MOUNT_ENCODER_POSITION_PROPERTY_NAME, items, ARRAY_SIZE(items));
		indigo_property *property = find_cached_property(MOUNT_ENCODER_POSITION_PROPERTY_NAME);
		SERIAL_CHECK_TRUE(property != NULL);
		SERIAL_CHECK_EQ_INT(INDIGO_NUMBER_VECTOR, property->type);
		SERIAL_CHECK_EQ_INT(INDIGO_RO_PERM, property->perm);
		SERIAL_CHECK_TRUE(!strcmp(property->group, MOUNT_ALIGNMENT_GROUP));
		indigo_item *ra_item = find_cached_item(MOUNT_ENCODER_POSITION_PROPERTY_NAME, MOUNT_ENCODER_POSITION_RA_ITEM_NAME);
		indigo_item *dec_item = find_cached_item(MOUNT_ENCODER_POSITION_PROPERTY_NAME, MOUNT_ENCODER_POSITION_DEC_ITEM_NAME);
		SERIAL_CHECK_TRUE(ra_item != NULL && dec_item != NULL);
		SERIAL_CHECK_TRUE(ra_item->number.min == -8388608 && ra_item->number.max == 8388607 && dec_item->number.min == -8388608 && dec_item->number.max == 8388607);
		SERIAL_CHECK_TRUE(!strcmp(ra_item->number.format, "%.0f") && !strcmp(dec_item->number.format, "%.0f"));
		double ra = NAN, dec = NAN;
		long expected_ra = 0, expected_dec = 0;
		SERIAL_CHECK_TRUE(synscan_fresh_encoder(&ra, &dec));
		synscan_simulated_encoder_counts(&simulator, &expected_ra, &expected_dec);
		printf("    encoder on %s only: RA %.0f DEC %.0f published, the simulator answers %s %ld\n", ra_encoder ? "RA" : "DEC", ra, dec, ra_encoder ? "RA" : "DEC", ra_encoder ? expected_ra : expected_dec);
		SERIAL_CHECK_TRUE(ra == (ra_encoder ? expected_ra : 0));
		SERIAL_CHECK_TRUE(dec == (ra_encoder ? 0 : expected_dec));
		SERIAL_CHECK_TRUE((ra_encoder ? ra : dec) != 0);
		SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, 0, ra_encoder ? ":d2" : ":d1", NULL, 0, NULL));
		SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, 0, ra_encoder ? ":d1" : ":d2", NULL, 0, NULL) > 0);
		double values[] = { 1, 1 };
		indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_ENCODER_POSITION_PROPERTY_NAME, ARRAY_SIZE(items), items, values);
		double after_ra = NAN, after_dec = NAN;
		SERIAL_CHECK_TRUE(synscan_fresh_encoder(&after_ra, &after_dec));
		SERIAL_CHECK_TRUE(after_ra == ra && after_dec == dec);
		stop_serial_driver(&synscan_mount);
		driver_started = false;
		stop_external_serial_simulator(&simulator);
	}

cleanup:
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// Both axes show the :d reply of their encoder as it is, minus 0x800000: at the start position the simulator's encoder
// counts, at its resolution of SIM_ENCODER_COUNTS per revolution, not scaled to steps and without the driver's zero
// position subtracted. The RA step counter starts at 0, where the count is the offset alone, so only DEC tells counts
// from steps here; synscan_mount_encoder_position_follows_a_goto does it for both axes away from the start.
static void synscan_mount_encoder_position_reports_raw_counts(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ra = NAN, dec = NAN;
	SERIAL_CHECK_TRUE(start_encoder_simulator(&simulator, "6007", "6007"));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, "start position", &ra, &dec));
	long ra_steps = synscan_replayed_step_counter(&simulator, '1') - 0x800000;
	long dec_steps = synscan_replayed_step_counter(&simulator, '2') - 0x800000;
	// the DEC axis stands a quarter turn from the step zero, which the encoder counts as a quarter of its resolution
	SERIAL_CHECK_TRUE(dec_steps != 0 && dec != dec_steps && dec != dec_steps + SIM_DEC_ENCODER_OFFSET);
	SERIAL_CHECK_TRUE(ra_steps == 0 || ra != ra_steps + SIM_RA_ENCODER_OFFSET);

cleanup:
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The counts follow the axes: after a GoTo to each side of the pier both axes show the new :d replies of the simulator,
// in encoder counts on both axes, which differ from the step counters plus the offsets there.
static void synscan_mount_encoder_position_follows_a_goto(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ra = NAN, dec = NAN, previous_ra = NAN, previous_dec = NAN;
	SERIAL_CHECK_TRUE(start_encoder_simulator(&simulator, "6007", "6007"));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, "start position", &previous_ra, &previous_dec));
	for (int side = 0; side < 2; side++) {
		double target_ha = side == 0 ? -2.5 : 2.5;
		double target_dec = 30;
		double ra_j2000 = synscan_j2000_ra_at_hour_angle(target_ha, &target_dec);
		SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, ra_j2000, target_dec));
		SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, side == 0 ? "GoTo to HA -2.5 h DEC +30 deg" : "GoTo to HA +2.5 h DEC +30 deg", &ra, &dec));
		SERIAL_CHECK_TRUE(ra != previous_ra && dec != previous_dec);
		long ra_steps = synscan_replayed_step_counter(&simulator, '1') - 0x800000;
		long dec_steps = synscan_replayed_step_counter(&simulator, '2') - 0x800000;
		SERIAL_CHECK_TRUE(ra_steps != 0 && ra != ra_steps + SIM_RA_ENCODER_OFFSET && dec != dec_steps + SIM_DEC_ENCODER_OFFSET);
		previous_ra = ra;
		previous_dec = dec;
	}

cleanup:
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// X_MOUNT_USE_ENCODERS switches the dual encoders of the firmware and nothing else; the coordinates always come from the
// step counters (:j). The simulator models an AZ-GTi: --encoder-counts 1068 against 864000 steps, the RA encoder 20
// counts and the DEC encoder -3 counts away from the counters, so enabling the dual encoders re-bases both counters onto
// the encoder grid, by about 6.7 and -1.0 degrees.
#define SIM_REBASE_RA_OFFSET             20
#define SIM_REBASE_DEC_OFFSET            -3
#define SIM_REBASE_OFFSETS_TEXT          "20,-3"

static bool start_rebase_simulator(external_serial_simulator *simulator) {
	const char *arguments[] = { "--encoder-counts", SIM_ENCODER_COUNTS_TEXT, "--encoder-offsets", SIM_REBASE_OFFSETS_TEXT, "--ra-features", "6007", "--dec-features", "6007", NULL };
	sim_encoder_offsets[0] = SIM_REBASE_RA_OFFSET;
	sim_encoder_offsets[1] = SIM_REBASE_DEC_OFFSET;
	return start_external_serial_simulator_with_args(simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE, arguments);
}

// The pointing of the date (hour angle, declination) and the side of the OTA of the given step counters in the northern
// hemisphere, by the axis geometry of the driver: the RA zero a quarter turn before 0x800000, the DEC zero at 0x800000.
static void synscan_steps_date_pointing(long ra_steps, long dec_steps, double *ha, double *dec, bool *ota_west) {
	double ra_position = (ra_steps - (0x800000 - SIM_STEPS_PER_REVOLUTION / 4)) / SIM_STEPS_PER_REVOLUTION;
	double dec_position = (dec_steps - 0x800000) / SIM_STEPS_PER_REVOLUTION;
	if (dec_position < 0) {
		dec_position += 1;
	}
	*ota_west = dec_position >= 0.25 && dec_position < 0.75;
	*dec = (*ota_west ? 0.5 - dec_position : dec_position < 0.25 ? dec_position : dec_position - 1) * 360;
	*ha = synscan_wrap_hours((*ota_west ? (ra_position < 0.5 ? ra_position : ra_position - 1) : ra_position - 0.5) * 24);
}

// The pointing of the date of J2000 raw coordinates at the sidereal time `lst`.
static void synscan_raw_date_pointing(double ra, double dec, double lst, double *ha, double *date_dec) {
	*date_dec = dec;
	indigo_j2k_to_jnow(&ra, date_dec);
	*ha = synscan_wrap_hours(lst - ra);
}

// The fresh published pointing is the one of the simulator's step counters, replayed from its log; prints both.
static bool synscan_pointing_matches_steps(external_serial_simulator *simulator, const char *where) {
	double ha = NAN, dec = NAN, expected_ha = NAN, expected_dec = NAN;
	bool ota_west = false;
	synscan_fresh_date_pointing(&ha, &dec);
	long ra_steps = synscan_replayed_step_counter(simulator, '1');
	long dec_steps = synscan_replayed_step_counter(simulator, '2');
	synscan_steps_date_pointing(ra_steps, dec_steps, &expected_ha, &expected_dec, &ota_west);
	printf("    %s: pointing HA %+.4f h DEC %+.4f deg, the step counters %ld %ld give HA %+.4f h DEC %+.4f deg\n", where, ha, dec, ra_steps - 0x800000, dec_steps - 0x800000, expected_ha, expected_dec);
	return fabs(synscan_wrap_hours(ha - expected_ha)) < 0.01 && fabs(dec - expected_dec) < 0.05;
}

// Switching the dual encoders on re-bases the step counters, and the client has the re-based pointing when the switch is
// answered, before any later poll; the polls keep reading the step counters, a GoTo with the encoders on ends at its
// target with matching coordinates, and switching them off leaves the counters as they are.
static void synscan_mount_use_encoders_rebases_and_keeps_step_counters(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ha = NAN, dec = NAN, expected_ha = NAN, expected_dec = NAN;
	bool ota_west = false;
	install_observer();
	SERIAL_CHECK_TRUE(start_rebase_simulator(&simulator));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(cached_number_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME) >= 0);
	atomic_store(&observed_longitude, cached_number_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LONGITUDE_ITEM_NAME));
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	double target_dec = 30;
	double target_ra = synscan_j2000_ra_at_hour_angle(-2.5, &target_dec);
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, target_ra, target_dec));
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "encoders off"));
	long ra_steps = synscan_replayed_step_counter(&simulator, '1');
	long dec_steps = synscan_replayed_step_counter(&simulator, '2');
	// on: the controller re-bases both counters, the handler publishes the pointing of the re-based counters
	atomic_store(&observed_encoders_ok, false);
	SERIAL_CHECK_TRUE(synscan_select_encoders(true, true));
	SERIAL_CHECK_TRUE(atomic_load(&observed_encoders_ok));
	long rebased_ra_steps = synscan_replayed_step_counter(&simulator, '1');
	long rebased_dec_steps = synscan_replayed_step_counter(&simulator, '2');
	synscan_steps_date_pointing(rebased_ra_steps, rebased_dec_steps, &expected_ha, &expected_dec, &ota_west);
	synscan_raw_date_pointing(atomic_load(&observed_encoders_raw_ra), atomic_load(&observed_encoders_raw_dec), atomic_load(&observed_encoders_lst), &ha, &dec);
	printf("    switched on: counters re-based by %+ld %+ld steps, the client had HA %+.4f h DEC %+.4f deg with the answer, the re-based counters give HA %+.4f h DEC %+.4f deg\n", rebased_ra_steps - ra_steps, rebased_dec_steps - dec_steps, ha, dec, expected_ha, expected_dec);
	SERIAL_CHECK_TRUE(labs(rebased_ra_steps - ra_steps) > 10000 && labs(rebased_dec_steps - dec_steps) > 1000);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(ha - expected_ha)) < 0.01 && fabs(dec - expected_dec) < 0.05);
	// the polls keep reading the step counters, the encoders only for X_MOUNT_ENCODER_POSITION
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(wait_for_synscan_polls(2));
	SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, mark, ":j1", NULL, 0, NULL) >= 2 && count_synscan_commands(&simulator, mark, ":j2", NULL, 0, NULL) >= 2);
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "encoders on"));
	// a GoTo with the encoders on ends at its target
	target_dec = 40;
	target_ra = synscan_j2000_ra_at_hour_angle(-1, &target_dec);
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, target_ra, target_dec));
	synscan_fresh_date_pointing(&ha, &dec);
	printf("    GoTo with the encoders on to HA -1.0000 h DEC +40.0000 deg reached HA %+.4f h DEC %+.4f deg\n", ha, dec);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(ha + 1)) < 0.01 && fabs(dec - 40) < 0.05);
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "after the GoTo"));
	// off: the counters stay where the controller has them, no position is set
	ra_steps = synscan_replayed_step_counter(&simulator, '1');
	dec_steps = synscan_replayed_step_counter(&simulator, '2');
	mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, mark, ":E", NULL, 0, NULL));
	SERIAL_CHECK_TRUE(synscan_replayed_step_counter(&simulator, '1') == ra_steps && synscan_replayed_step_counter(&simulator, '2') == dec_steps);
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "encoders off again"));
	synscan_fresh_date_pointing(&ha, &dec);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(ha + 1)) < 0.01 && fabs(dec - 40) < 0.05);

cleanup:
	if (driver_started) {
		synscan_select_encoders(false, false);
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
	remove_observer();
}

// With the dual encoders on, the side of pier comes from the step counters too, and a park saves the step counters in
// the park file, not encoder counts, so the position restored after a power cycle is right.
static void synscan_mount_use_encoders_keeps_side_of_pier_and_park_in_steps(void) {
	static const char *items[] = { MOUNT_PARK_POSITION_HA_ITEM_NAME, MOUNT_PARK_POSITION_DEC_ITEM_NAME };
	double values[] = { 2, 35 };
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ha = NAN, dec = NAN;
	char park_path[PATH_MAX];
	synscan_park_file_path(park_path, sizeof(park_path));
	synscan_remove_park_file();
	SERIAL_CHECK_TRUE(start_rebase_simulator(&simulator));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(cached_number_value(GEOGRAPHIC_COORDINATES_PROPERTY_NAME, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME) >= 0);
	SERIAL_CHECK_TRUE(synscan_select_encoders(true, true));
	// west of the meridian the OTA is east of the pier
	double target_dec = 30;
	double target_ra = synscan_j2000_ra_at_hour_angle(2.5, &target_dec);
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, target_ra, target_dec));
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "GoTo with the encoders on"));
	bool east = find_cached_item(MOUNT_SIDE_OF_PIER_PROPERTY_NAME, MOUNT_SIDE_OF_PIER_EAST_ITEM_NAME)->sw.value;
	printf("    at HA +2.5 h DEC +30 deg the side of pier is %s\n", east ? "east" : "west");
	SERIAL_CHECK_TRUE(east);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_PARK_POSITION_PROPERTY_NAME, 2, items, values));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_PARK_POSITION_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_PARK_PROPERTY_NAME, INDIGO_OK_STATE));
	synscan_fresh_date_pointing(&ha, &dec);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(ha - values[0])) < 0.01 && fabs(dec - values[1]) < 0.05);
	long ra_steps = synscan_replayed_step_counter(&simulator, '1');
	long dec_steps = synscan_replayed_step_counter(&simulator, '2');
	long saved_ra = -1, saved_dec = -1;
	FILE *file = fopen(park_path, "r");
	SERIAL_CHECK_TRUE(file != NULL);
	int fields = fscanf(file, "%lx %lx", &saved_ra, &saved_dec);
	fclose(file);
	printf("    parked at HA %+.4f h DEC %+.4f deg: the park file holds %06lx %06lx, the step counters are %06lx %06lx\n", ha, dec, saved_ra, saved_dec, ra_steps, dec_steps);
	SERIAL_CHECK_EQ_INT(2, fields);
	SERIAL_CHECK_TRUE(saved_ra == ra_steps && saved_dec == dec_steps);
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME, true));

cleanup:
	if (driver_started) {
		synscan_select_encoders(false, false);
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
	synscan_remove_park_file();
}

// X_MOUNT_USE_ENCODERS sends the dual encoder commands and nothing else. The default simulator's encoders read the step
// counters plus 512 and 1024 steps and need no re-base, so the pointing stays where the step counters have it; the
// driver used to read the encoders as steps here and moved the coordinates by those offsets.
static void synscan_mount_use_encoders_switches_only_the_dual_encoders(void) {
	external_serial_simulator simulator = { 0 };
	double ha = NAN, dec = NAN, initial_ha = NAN, initial_dec = NAN;
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	SERIAL_CHECK_TRUE(context.connected && context.last_connection_state == INDIGO_OK_STATE);
	// away from the pole, where the hour angle of the raw coordinates is not defined
	double target_dec = 40;
	double target_ra = synscan_j2000_ra_at_hour_angle(-2, &target_dec);
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, target_ra, target_dec));
	synscan_fresh_date_pointing(&initial_ha, &initial_dec);
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(synscan_select_encoders(true, true));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":W1040000", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":W2040000", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, mark, ":E", NULL, 0, NULL));
	synscan_fresh_date_pointing(&ha, &dec);
	printf("    pointing HA %+.4f h DEC %+.4f deg with the encoders off, HA %+.4f h DEC %+.4f deg with them on\n", initial_ha, initial_dec, ha, dec);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(ha - initial_ha)) < 0.01 && fabs(dec - initial_dec) < 0.05);
	mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":W1050000", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":W2050000", NULL, 0, NULL));

cleanup:
	if (context.connected) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The controller keeps the dual encoder setting of the last command it got, which no query reports. The driver sends
// the item at connect, before reading the axes: a new driver turns the encoders off, a reconnect turns them on again when
// they were on, and the pointing after the reconnect is the one of the step counters.
static void synscan_mount_use_encoders_agree_with_the_controller_after_connect(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	SERIAL_CHECK_TRUE(start_rebase_simulator(&simulator));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	assert_switch_item_value(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_RA_ENCODER_ITEM_NAME, false);
	assert_switch_item_value(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_DEC_ENCODER_ITEM_NAME, false);
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_USE_ENCODERS_PROPERTY_NAME)->state);
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, 0, ":W1050000", NULL, 0, NULL));
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, 0, ":W2050000", NULL, 0, NULL));
	SERIAL_CHECK_TRUE(first_synscan_command_line(&simulator, 0, ":W2050000") < first_synscan_command_line(&simulator, 0, ":j1"));
	SERIAL_CHECK_TRUE(synscan_select_encoders(true, true));
	disconnect_serial_device(&synscan_mount);
	int mark = synscan_mark(&simulator);
	SERIAL_CHECK_TRUE(connect_serial_device(&synscan_mount, simulator.port));
	assert_switch_item_value(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_RA_ENCODER_ITEM_NAME, true);
	assert_switch_item_value(MOUNT_USE_ENCODERS_PROPERTY_NAME, MOUNT_USE_DEC_ENCODER_ITEM_NAME, true);
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, find_cached_property(MOUNT_USE_ENCODERS_PROPERTY_NAME)->state);
	int on = first_synscan_command_line(&simulator, mark, ":W2040000");
	int first_reading = first_synscan_command_line(&simulator, mark, ":j1");
	printf("    reconnect: :W1040000 sent %d time(s), :W2040000 at line %d, the first :j1 at line %d\n", count_synscan_commands(&simulator, mark, ":W1040000", NULL, 0, NULL), on, first_reading);
	SERIAL_CHECK_EQ_INT(1, count_synscan_commands(&simulator, mark, ":W1040000", NULL, 0, NULL));
	SERIAL_CHECK_TRUE(on >= 0 && on < first_reading);
	SERIAL_CHECK_TRUE(synscan_pointing_matches_steps(&simulator, "after the reconnect"));

cleanup:
	if (driver_started) {
		if (context.connected) {
			synscan_select_encoders(false, false);
			stop_serial_driver(&synscan_mount);
		} else {
			tear_down_serial_driver(&synscan_mount);
		}
	}
	stop_external_serial_simulator(&simulator);
}

// A sync changes the alignment model, not the axes: the coordinates move to the synced place, the encoder counts of
// the standing axes stay exactly as they were.
static void synscan_mount_encoder_position_ignores_a_sync(void) {
	static const char *items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ra = NAN, dec = NAN, synced_ra = NAN, synced_dec = NAN;
	SERIAL_CHECK_TRUE(start_encoder_simulator(&simulator, "6007", "6007"));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	SERIAL_CHECK_EQ_INT(0, synscan_alignment_point_count());
	// a sync within 5 degrees of the pole is refused, so the mount leaves its start position first; tracking stays off
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 40));
	SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, "before the sync", &ra, &dec));
	double coordinates_ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double values[] = { fmod(coordinates_ra + 1, 24), cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) - 5 };
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, ARRAY_SIZE(items), items, values));
	SERIAL_CHECK_TRUE(wait_for_synscan_alignment_point_count(1));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	synscan_fresh_raw(MOUNT_RAW_COORDINATES_RA_ITEM_NAME);
	double synced_coordinates_ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double synced_coordinates_dec = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, "after the sync", &synced_ra, &synced_dec));
	printf("    synced to %.4f h %+.4f deg, coordinates %.4f h %+.4f deg\n", values[0], values[1], synced_coordinates_ra, synced_coordinates_dec);
	SERIAL_CHECK_TRUE(fabs(synscan_wrap_hours(synced_coordinates_ra - values[0])) < 0.01);
	SERIAL_CHECK_TRUE(fabs(synced_coordinates_dec - values[1]) < 0.01);
	SERIAL_CHECK_TRUE(synced_ra == ra && synced_dec == dec);

cleanup:
	if (driver_started) {
		if (synscan_alignment_point_count() > 0) {
			indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ALIGNMENT_DELETE_POINTS_PROPERTY_NAME, MOUNT_ALIGNMENT_DELETE_ALL_POINTS_ITEM_NAME, true);
			ASSERT_TRUE(wait_for_synscan_alignment_point_count(0));
		}
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// A refused or malformed encoder reply, at connect or in a poll, publishes X_MOUNT_ENCODER_POSITION ALERT with the last
// valid values and leaves the coordinates alone; a failed step counter query marks both. The next good poll restores
// OK and the connection stays up.
static void synscan_mount_encoder_position_alert_on_a_failed_query(void) {
	static const char *prefixes[] = { ":d1", ":d2", ":j1" };
	static const char *replies[] = { "!0", "=1", "!0" };
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	double ra = NAN, dec = NAN;
	install_observer();
	SERIAL_CHECK_TRUE(start_encoder_simulator(&simulator, "6007", "6007"));
	SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, ":d1", "!0", 1));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(context.connected && context.last_connection_state == INDIGO_OK_STATE);
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	printf("    refused encoder reading at connect: encoder position defined with state %d, coordinates with state %d\n", atomic_load(&observed_encoder_define_state), atomic_load(&observed_coordinates_define_state));
	SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, atomic_load(&observed_encoder_define_state));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, atomic_load(&observed_coordinates_define_state));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_ENCODER_POSITION_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(synscan_select_encoders(false, false));
	for (int i = 0; i < ARRAY_SIZE(prefixes); i++) {
		SERIAL_CHECK_TRUE(synscan_encoder_matches_simulator(&simulator, "before the fault", &ra, &dec));
		atomic_store(&observed_encoder_alert, false);
		unsigned int coordinates_alert = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE);
		SERIAL_CHECK_TRUE(write_synscan_fault(&simulator, prefixes[i], replies[i], 1));
		for (int j = 0; j < 60 && !atomic_load(&observed_encoder_alert); j++) {
			indigo_usleep(50000);
		}
		SERIAL_CHECK_TRUE(atomic_load(&observed_encoder_alert));
		bool coordinates_alerted = property_state_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_ALERT_STATE) > coordinates_alert;
		printf("    %s answered %s: ALERT with RA %.0f DEC %.0f, the previous publication RA %.0f DEC %.0f, coordinates %s\n", prefixes[i], replies[i], atomic_load(&observed_encoder_alert_ra), atomic_load(&observed_encoder_alert_dec), atomic_load(&observed_encoder_alert_previous_ra), atomic_load(&observed_encoder_alert_previous_dec), coordinates_alerted ? "ALERT" : "not ALERT");
		SERIAL_CHECK_TRUE(atomic_load(&observed_encoder_alert_ra) == atomic_load(&observed_encoder_alert_previous_ra));
		SERIAL_CHECK_TRUE(atomic_load(&observed_encoder_alert_dec) == atomic_load(&observed_encoder_alert_previous_dec));
		SERIAL_CHECK_TRUE(atomic_load(&observed_encoder_alert_ra) == ra && atomic_load(&observed_encoder_alert_dec) == dec);
		SERIAL_CHECK_TRUE(coordinates_alerted == (prefixes[i][1] == 'j'));
		unsigned int ok = property_state_revision(MOUNT_ENCODER_POSITION_PROPERTY_NAME, INDIGO_OK_STATE);
		SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(MOUNT_ENCODER_POSITION_PROPERTY_NAME, INDIGO_OK_STATE, ok));
		SERIAL_CHECK_TRUE(context.connected);
	}

cleanup:
	remove_observer();
	remove_synscan_fault(&simulator);
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The first publication of the equatorial coordinates after the request is its refusal: ALERT with `reason`, at the
// position the mount reported before it, together with the horizontal coordinates in ALERT. No publication carries
// another position and none is ALERT right after an OK: the poll may still publish the running motion BUSY after the
// refusal and its end OK, but no refusal follows the end of the motion.
static bool synscan_check_refused_during_motion(const char *label, const coordinates_publication *events, int count, const char *reason, double ra0, double dec0, double tolerance) {
	int refusal = -1;
	bool ok = true;
	for (int i = 0; i < count && refusal < 0; i++) {
		if (events[i].kind == 'E') {
			refusal = i;
		}
	}
	if (refusal < 0 || events[refusal].state != INDIGO_ALERT_STATE) {
		fprintf(stderr, "    %s: the first publication of the coordinates after the request (%d) is not the refusal\n", label, refusal);
		ok = false;
	} else if (refusal == 0 || events[refusal - 1].kind != 'H' || events[refusal - 1].state != INDIGO_ALERT_STATE) {
		fprintf(stderr, "    %s: the refusal %d is not published with the horizontal coordinates in ALERT\n", label, refusal);
		ok = false;
	} else if (!atomic_load(&gate_alert_message_seen) || strcmp(gate_alert_message, reason)) {
		fprintf(stderr, "    %s: the refusal carries '%s', not '%s'\n", label, atomic_load(&gate_alert_message_seen) ? gate_alert_message : "", reason);
		ok = false;
	}
	indigo_property_state previous = INDIGO_IDLE_STATE;
	for (int i = refusal + 1; ok && i < count; i++) {
		if (events[i].kind != 'E') {
			continue;
		}
		if (events[i].state == INDIGO_ALERT_STATE && previous == INDIGO_OK_STATE) {
			fprintf(stderr, "    %s: ALERT published at %d after the OK that ended the motion\n", label, i);
			ok = false;
		}
		previous = events[i].state;
	}
	if (!ok) {
		print_coordinates_publications(label, events, count);
		return false;
	}
	return check_position_kept(label, events, count, 0, ra0, dec0, tolerance);
}

// A coordinates request sent while a park or a homing runs is refused before its BUSY with `reason`, without a command.
// The motion goes to the current position and ends on the first run of its finalizer, which comes due while a gate holds
// the queue right after the motion handler, so the finalizer, a time critical task, runs ahead of a change handler the
// request queued. A request admitted there would get BUSY, then the OK of the motion's end over it, then the refusal of
// its handler. With `queued` the gate holds the queue before the motion request, so the coordinates request comes after
// the motion request was admitted but before its handler ran; it is refused the same way, and the motion still runs.
static void synscan_check_request_refused_during_motion(const char *label, const char *set_property, const char *set_item, const char *motion_property, const char *motion_item, const char *light_item, const char *on_set, const char *reason, bool queued) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	static coordinates_publication events[COORDINATES_PUBLICATIONS_SIZE];
	install_gate();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, set_property, set_item, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(set_property, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_for_switch_item_value(set_property, set_item, false));
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, on_set, true));
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	double ra0 = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	double dec0 = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	int mark = synscan_mark(&simulator);
	if (queued) {
		SERIAL_CHECK_TRUE(hold_device_queue());
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, motion_property, motion_item, true));
	} else {
		// the gate queued from the busy light of this motion, not a gate of an earlier case or step
		atomic_store(&gate_entered, false);
		atomic_store(&gate_on_busy_light, light_item);
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, motion_property, motion_item, true));
		SERIAL_CHECK_TRUE(wait_for_gate());
	}
	// The motion request is admitted, the finalizer has not run yet
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(motion_property)->state);
	start_coordinates_publications(synscan_mount.device_name);
	atomic_store(&gate_alert_message_seen, false);
	atomic_store(&gate_record_alert_message, true);
	const char *items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	double values[] = { fmod(ra0 + 1, 24), 10 };
	unsigned int revision = property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, ARRAY_SIZE(items), items, values));
	// Answered on the bus, refused or admitted with BUSY, while the gate still holds the queue
	for (int i = 0; i < 100 && property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME) == revision; i++) {
		indigo_usleep(10000);
	}
	SERIAL_CHECK_TRUE(property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME) != revision);
	// The finalizer was scheduled 0.2 s after the motion handler, which returned before the gate entered
	indigo_usleep(300000);
	atomic_store(&gate_release, true);
	SERIAL_CHECK_TRUE(wait_for_property_state_long(motion_property, INDIGO_OK_STATE));
	// two polls of the idle mount, the change handler of an admitted request publishes its result before them
	unsigned int polled = property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME);
	for (int i = 0; i < 100 && property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME) < polled + 2; i++) {
		indigo_usleep(100000);
	}
	int count = stop_coordinates_publications(events);
	atomic_store(&gate_record_alert_message, false);
	SERIAL_CHECK_TRUE(synscan_check_refused_during_motion(label, events, count, reason, ra0, dec0, 0.1));
	// the motion sent no slew of its own here, the refused request none at all
	SERIAL_CHECK_EQ_INT(0, synscan_motion_commands(&simulator, mark));
	SERIAL_CHECK_TRUE(find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state != INDIGO_BUSY_STATE);
cleanup:
	stop_coordinates_publications(NULL);
	remove_gate();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
	// a park leaves its position file, which the next connection would restore
	synscan_remove_park_file();
}

static void synscan_mount_goto_during_homing_is_refused(void) {
	synscan_check_request_refused_during_motion("GOTO during homing", MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, MOUNT_STATE_HOME_ITEM_NAME, MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, "Mount is homing", false);
}

static void synscan_mount_sync_during_homing_is_refused(void) {
	synscan_check_request_refused_during_motion("SYNC during homing", MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, MOUNT_STATE_HOME_ITEM_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, "Mount is homing", false);
}

// The home request claims the homing when it is admitted: a GOTO or SYNC sent right after it, while its handler still
// waits in the queue, is refused as during the homing. It used to be admitted, the GOTO then claimed the axes and the
// home handler refused the home, the SYNC was carried out after the home.
static void synscan_mount_goto_queued_behind_home_is_refused(void) {
	synscan_check_request_refused_during_motion("GOTO queued behind a home", MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, MOUNT_STATE_HOME_ITEM_NAME, MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, "Mount is homing", true);
}

static void synscan_mount_sync_queued_behind_home_is_refused(void) {
	synscan_check_request_refused_during_motion("SYNC queued behind a home", MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, MOUNT_STATE_HOME_ITEM_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, "Mount is homing", true);
}

// The same for an auto home: a GOTO sent while the auto home handler waits in the queue is refused with ALERT and
// "Mount is homing", without its BUSY, and the auto home starts instead of being refused as "mount is busy".
static void synscan_mount_goto_queued_behind_autohome_is_refused(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	static coordinates_publication events[COORDINATES_PUBLICATIONS_SIZE];
	install_gate();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_set_switch(MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	double ra0 = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	SERIAL_CHECK_TRUE(hold_device_queue());
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_AUTOHOME_PROPERTY_NAME, MOUNT_AUTOHOME_ITEM_NAME, true));
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_AUTOHOME_PROPERTY_NAME)->state);
	start_coordinates_publications(synscan_mount.device_name);
	atomic_store(&gate_alert_message_seen, false);
	atomic_store(&gate_record_alert_message, true);
	const char *items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	double values[] = { fmod(ra0 + 1, 24), 10 };
	unsigned int revision = property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, synscan_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, ARRAY_SIZE(items), items, values));
	for (int i = 0; i < 100 && property_revision(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME) == revision; i++) {
		indigo_usleep(10000);
	}
	int count = stop_coordinates_publications(events);
	atomic_store(&gate_record_alert_message, false);
	atomic_store(&gate_release, true);
	int refusal = -1;
	for (int i = 0; i < count && refusal < 0; i++) {
		if (events[i].kind == 'E') {
			refusal = i;
		}
	}
	printf("    GOTO queued behind an auto home: first coordinates publication %d, state %d, message '%s'\n", refusal, refusal >= 0 ? events[refusal].state : -1, atomic_load(&gate_alert_message_seen) ? gate_alert_message : "");
	SERIAL_CHECK_TRUE(refusal > 0 && events[refusal].state == INDIGO_ALERT_STATE && events[refusal - 1].kind == 'H' && events[refusal - 1].state == INDIGO_ALERT_STATE);
	SERIAL_CHECK_TRUE(atomic_load(&gate_alert_message_seen) && !strcmp(gate_alert_message, "Mount is homing"));
	SERIAL_CHECK_TRUE(events[refusal].target[0] != values[0] || events[refusal].target[1] != values[1]);
	// the auto home was started, not refused, and is aborted to end the case
	SERIAL_CHECK_TRUE(wait_for_light_item_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_HOME_ITEM_NAME, INDIGO_BUSY_STATE));
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_AUTOHOME_PROPERTY_NAME)->state);
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_AUTOHOME_PROPERTY_NAME, INDIGO_ALERT_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_ABORT_MOTION_PROPERTY_NAME, INDIGO_OK_STATE));
cleanup:
	stop_coordinates_publications(NULL);
	remove_gate();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The park request sets the parked switch, so the parked-mount guard of the change branch refuses the request
static void synscan_mount_goto_during_parking_is_refused(void) {
	synscan_check_request_refused_during_motion("GOTO during parking", MOUNT_PARK_SET_PROPERTY_NAME, MOUNT_PARK_SET_CURRENT_ITEM_NAME, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, MOUNT_STATE_PARK_ITEM_NAME, MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, "Mount is parked!", false);
}

// ---- Late replies after a repeated UDP command
//
// A UDP command whose reply is slower than the reply timeout is sent again and ends on the first reply; the other one
// arrives later. Taken for the reply to the next query of the same length it would publish another axis's value. The
// AZ-GTi answered in 0.25-0.42 s for several seconds at a time.

// Waits until the simulator has used up the fault rules, then for two more equatorial publications of the polls that
// follow; a repeated query is no new poll, so the publications are counted, not the queries.
static bool udp_wait_after_faults(external_serial_simulator *simulator) {
	static coordinates_publication events[COORDINATES_PUBLICATIONS_SIZE];
	for (int i = 0; i < 600 && synscan_fault_pending(simulator); i++) {
		indigo_usleep(50000);
	}
	if (synscan_fault_pending(simulator)) {
		return false;
	}
	int seen = -1;
	double deadline = indigo_monotonic_time() + 5;
	while (indigo_monotonic_time() < deadline) {
		int count = copy_coordinates_publications(events);
		int published = 0;
		for (int i = 0; i < count; i++) {
			published += events[i].kind == 'E';
		}
		if (seen < 0) {
			seen = published;
		} else if (published >= seen + 2) {
			return true;
		}
		indigo_usleep(20000);
	}
	fprintf(stderr, "    fewer than two polls published the coordinates within 5 s\n");
	return false;
}

// Every equatorial publication recorded since `start` stays at the position the mount had: no other axis's counter is
// taken for a position. Without tracking the RA of the date follows the sidereal time, a few seconds are far below 0.05 h.
static bool udp_positions_kept(const char *label, double ra0, double dec0, int *published) {
	static coordinates_publication events[COORDINATES_PUBLICATIONS_SIZE];
	int count = stop_coordinates_publications(events);
	bool ok = true;
	*published = 0;
	for (int i = 0; i < count; i++) {
		if (events[i].kind != 'E') {
			continue;
		}
		(*published)++;
		double ra_error = fabs(events[i].value[0] - ra0);
		if (ra_error > 12) {
			ra_error = 24 - ra_error;
		}
		if (ra_error > 0.05 || fabs(events[i].value[1] - dec0) > 0.05) {
			fprintf(stderr, "    %s: publication %d RA %.4f DEC %.4f, the mount is at RA %.4f DEC %.4f\n", label, i, events[i].value[0], events[i].value[1], ra0, dec0);
			ok = false;
		}
	}
	return ok;
}

typedef struct {
	const char *label;
	const char *rules;
} udp_stray_round;

// In each round late replies of the poll's queries are injected after a poll; the positions published by the next polls
// stay at the mount's position.
static void synscan_udp_late_replies_keep_positions(const udp_stray_round *rounds, int count) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	SERIAL_CHECK_TRUE(start_udp_simulator(&simulator, 0));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	// RA and DEC counters far apart
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 20));
	for (int round = 0; round < count; round++) {
		int published = 0;
		SERIAL_CHECK_TRUE(udp_wait_for_poll(&simulator));
		double ra0 = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
		double dec0 = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
		start_coordinates_publications(synscan_mount.device_name);
		SERIAL_CHECK_TRUE(write_synscan_faults(&simulator, rounds[round].rules));
		SERIAL_CHECK_TRUE(udp_wait_after_faults(&simulator));
		bool kept = udp_positions_kept(rounds[round].label, ra0, dec0, &published);
		printf("    %s: %d equatorial publications, all at RA %.4f DEC %.4f: %s\n", rounds[round].label, published, ra0, dec0, kept ? "yes" : "no");
		SERIAL_CHECK_TRUE(published >= 2);
		SERIAL_CHECK_TRUE(kept);
		SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	}
cleanup:
	stop_coordinates_publications(NULL);
	remove_synscan_fault(&simulator);
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// The DEC reply arrives 250 ms late, after the repeated query was answered, while the RA query waits for its own reply,
// which is 100 ms late.
static void synscan_udp_late_dec_reply_is_not_taken_for_ra(void) {
	static const udp_stray_round rounds[] = { { "late DEC reply", ":j2 late:250 1\n:j1 late:100 1\n" } };
	synscan_udp_late_replies_keep_positions(rounds, ARRAY_SIZE(rounds));
}

// Every reply takes 300 ms for about six polls, so every query is sent twice.
static void synscan_udp_sustained_latency_keeps_positions(void) {
	static const udp_stray_round rounds[] = { { "300 ms replies", ": late:300 24\n" } };
	synscan_udp_late_replies_keep_positions(rounds, ARRAY_SIZE(rounds));
}

// Both replies late past one timeout; a DEC reply later than the RA query's send; two late DEC replies.
static void synscan_udp_late_query_reply_variants_keep_positions(void) {
	static const udp_stray_round rounds[] = {
		{ "DEC and RA replies 250 ms late", ":j2 late:250 1\n:j1 late:250 1\n" },
		{ "DEC reply 350 ms late, RA reply 100 ms late", ":j2 late:350 1\n:j1 late:100 1\n" },
		{ "DEC reply 450 ms late twice, RA reply 150 ms late", ":j2 late:450 2\n:j1 late:150 1\n" }
	};
	synscan_udp_late_replies_keep_positions(rounds, ARRAY_SIZE(rounds));
}

// The GoTo finalizer reads the status of RA and then of DEC. With RA arrived and DEC still moving, the RA status reply
// arrives 250 ms late, after the repeated query was answered, while the DEC status query waits for its own reply. Taken
// for the DEC status it would end the GoTo while DEC still moves: the GoTo ends OK only after DEC arrived.
static void synscan_udp_late_status_reply_does_not_end_goto(void) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	SERIAL_CHECK_TRUE(start_udp_simulator(&simulator, 0));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_TRUE(synscan_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(synscan_lst() - 2 + 24, 24), 20));
	double ra = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME);
	int mark = synscan_mark(&simulator);
	// RA moves 15 minutes at high speed and arrives first, DEC moves 60 degrees
	SERIAL_CHECK_TRUE(synscan_start_goto(MOUNT_ON_COORDINATES_SET_SLEW_ITEM_NAME, fmod(ra + 0.25, 24), 80));
	for (int i = 0; i < 500 && count_synscan_commands(&simulator, mark, "@arrived1", NULL, 0, NULL) == 0; i++) {
		indigo_usleep(10000);
	}
	SERIAL_CHECK_TRUE(count_synscan_commands(&simulator, mark, "@arrived1", NULL, 0, NULL) > 0);
	SERIAL_CHECK_EQ_INT(0, count_synscan_commands(&simulator, mark, "@arrived2", NULL, 0, NULL));
	SERIAL_CHECK_TRUE(write_synscan_faults(&simulator, ":f1 late:250 1\n:f2 late:100 1\n"));
	SERIAL_CHECK_TRUE(wait_for_property_state_long(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	int dec_arrived = count_synscan_commands(&simulator, mark, "@arrived2", NULL, 0, NULL);
	double dec = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	printf("    GoTo ended with DEC %s, DEC %.3f\n", dec_arrived > 0 ? "arrived" : "still moving", dec);
	SERIAL_CHECK_TRUE(!synscan_fault_pending(&simulator));
	SERIAL_CHECK_TRUE(dec_arrived > 0);
	SERIAL_CHECK_TRUE(fabs(dec - 80) < 0.1);
cleanup:
	remove_synscan_fault(&simulator);
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
}

// Park and home claim the axes when their request is admitted. With both requests admitted while a gate holds the queue,
// the first one runs and the second one is refused, whichever comes first.
static void synscan_check_queued_park_and_home(bool park_first) {
	external_serial_simulator simulator = { 0 };
	bool driver_started = false;
	install_gate();
	SERIAL_CHECK_TRUE(start_external_serial_simulator(&simulator, MOUNT_SYNSCAN_SIMULATOR_EXECUTABLE));
	SERIAL_CHECK_TRUE(start_serial_driver(&synscan_mount, simulator.port));
	driver_started = true;
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_PARK_SET_PROPERTY_NAME, MOUNT_PARK_SET_CURRENT_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_switch_item_value(MOUNT_PARK_SET_PROPERTY_NAME, MOUNT_PARK_SET_CURRENT_ITEM_NAME, false));
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, true));
	SERIAL_CHECK_TRUE(wait_for_switch_item_value(MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, false));
	SERIAL_CHECK_TRUE(hold_device_queue());
	for (int i = 0; i < 2; i++) {
		if ((i == 0) == park_first) {
			SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true));
		} else {
			SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_switch_property_1(&simulator_test_client, synscan_mount.device_name, MOUNT_HOME_PROPERTY_NAME, MOUNT_HOME_ITEM_NAME, true));
		}
	}
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_PARK_PROPERTY_NAME)->state);
	SERIAL_CHECK_EQ_INT(INDIGO_BUSY_STATE, find_cached_property(MOUNT_HOME_PROPERTY_NAME)->state);
	atomic_store(&gate_release, true);
	SERIAL_CHECK_TRUE(wait_for_property_not_busy(MOUNT_PARK_PROPERTY_NAME));
	SERIAL_CHECK_TRUE(wait_for_property_not_busy(MOUNT_HOME_PROPERTY_NAME));
	indigo_property_state park = find_cached_property(MOUNT_PARK_PROPERTY_NAME)->state;
	indigo_property_state home = find_cached_property(MOUNT_HOME_PROPERTY_NAME)->state;
	printf("    %s first: park ends %d, home ends %d\n", park_first ? "park" : "home", park, home);
	if (park_first) {
		SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, park);
		SERIAL_CHECK_TRUE(wait_for_switch_item_value(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true));
		SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, home);
	} else {
		SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, home);
		SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, park);
		SERIAL_CHECK_TRUE(wait_for_switch_item_value(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME, true));
	}
	SERIAL_CHECK_TRUE(wait_for_light_item_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_SLEW_ITEM_NAME, INDIGO_IDLE_STATE));
cleanup:
	remove_gate();
	if (driver_started) {
		stop_serial_driver(&synscan_mount);
	}
	stop_external_serial_simulator(&simulator);
	synscan_remove_park_file();
}

static void synscan_mount_home_queued_behind_park_is_refused(void) {
	synscan_check_queued_park_and_home(true);
}

static void synscan_mount_park_queued_behind_home_is_refused(void) {
	synscan_check_queued_park_and_home(false);
}

